// HVAC Business Dashboard - HTML Generator
// No goldplating. It works.

const data = $input.first().json;

// Handle empty/null data
const stats = {
  total_events: data.total_events || 0,
  emergencies: data.emergencies || 0,
  appointments: data.appointments || 0,
  inquiries: data.inquiries || 0,
  revenue_captured: data.revenue_captured || 0,
  avg_urgency: data.avg_urgency || 0,
  decisions_made: data.decisions_made || 0,
  confidence_pct: data.confidence_pct || 0,
  agents_active: data.agents_active || 0,
  minutes_saved: data.minutes_saved || 0,
  ai_cost: data.ai_cost || 0
};

// Calculate derived values
const hoursSaved = (stats.minutes_saved / 60).toFixed(1);
const roi = stats.ai_cost > 0 ? Math.round(stats.revenue_captured / stats.ai_cost) : 0;

const html = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Climate Control Co. - Dashboard</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: #0f172a;
            color: #e2e8f0;
            min-height: 100vh;
            padding: 2rem;
        }
        .header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 2rem;
            padding-bottom: 1rem;
            border-bottom: 1px solid #334155;
        }
        .header h1 {
            font-size: 1.5rem;
            color: #38bdf8;
        }
        .timestamp {
            color: #64748b;
            font-size: 0.875rem;
        }
        .hero-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 1.5rem;
            margin-bottom: 2rem;
        }
        .hero-card {
            background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
            border: 1px solid #334155;
            border-radius: 12px;
            padding: 1.5rem;
            text-align: center;
        }
        .hero-card.revenue {
            border-color: #22c55e;
            background: linear-gradient(135deg, #14532d 0%, #0f172a 100%);
        }
        .hero-value {
            font-size: 2.5rem;
            font-weight: 700;
            color: #f8fafc;
        }
        .hero-card.revenue .hero-value {
            color: #4ade80;
        }
        .hero-label {
            font-size: 0.875rem;
            color: #94a3b8;
            margin-top: 0.5rem;
        }
        .section {
            background: #1e293b;
            border-radius: 12px;
            padding: 1.5rem;
            margin-bottom: 1.5rem;
        }
        .section h2 {
            font-size: 1rem;
            color: #94a3b8;
            margin-bottom: 1rem;
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }
        .stats-row {
            display: flex;
            justify-content: space-between;
            padding: 0.75rem 0;
            border-bottom: 1px solid #334155;
        }
        .stats-row:last-child {
            border-bottom: none;
        }
        .stat-label { color: #94a3b8; }
        .stat-value { color: #f8fafc; font-weight: 600; }
        .stat-value.positive { color: #4ade80; }
        .footer {
            text-align: center;
            color: #475569;
            font-size: 0.75rem;
            margin-top: 2rem;
        }
        .refresh-btn {
            display: inline-block;
            margin-top: 1rem;
            padding: 0.5rem 1.5rem;
            background: #334155;
            color: #e2e8f0;
            border: none;
            border-radius: 6px;
            cursor: pointer;
            font-size: 0.875rem;
        }
        .refresh-btn:hover {
            background: #475569;
        }
    </style>
</head>
<body>
    <div class="header">
        <h1>🏠 Climate Control Co.</h1>
        <div class="timestamp">
            Updated: ${new Date().toLocaleString()}
        </div>
    </div>

    <div class="hero-grid">
        <div class="hero-card revenue">
            <div class="hero-value">$${Number(stats.revenue_captured).toLocaleString()}</div>
            <div class="hero-label">Revenue Captured Today</div>
        </div>
        <div class="hero-card">
            <div class="hero-value">${hoursSaved}h</div>
            <div class="hero-label">Time Saved Today</div>
        </div>
        <div class="hero-card">
            <div class="hero-value">${stats.total_events}</div>
            <div class="hero-label">Events Handled</div>
        </div>
        <div class="hero-card">
            <div class="hero-value">${roi}x</div>
            <div class="hero-label">ROI (Revenue / AI Cost)</div>
        </div>
    </div>

    <div class="section">
        <h2>📊 Today's Activity</h2>
        <div class="stats-row">
            <span class="stat-label">🚨 Emergencies Handled</span>
            <span class="stat-value">${stats.emergencies}</span>
        </div>
        <div class="stats-row">
            <span class="stat-label">📅 Appointments Scheduled</span>
            <span class="stat-value">${stats.appointments}</span>
        </div>
        <div class="stats-row">
            <span class="stat-label">❓ Inquiries Answered</span>
            <span class="stat-value">${stats.inquiries}</span>
        </div>
    </div>

    <div class="section">
        <h2>🤖 Agent Performance</h2>
        <div class="stats-row">
            <span class="stat-label">Decisions Made</span>
            <span class="stat-value">${stats.decisions_made}</span>
        </div>
        <div class="stats-row">
            <span class="stat-label">Avg Confidence</span>
            <span class="stat-value">${stats.confidence_pct}%</span>
        </div>
        <div class="stats-row">
            <span class="stat-label">Agents Active</span>
            <span class="stat-value">${stats.agents_active}</span>
        </div>
        <div class="stats-row">
            <span class="stat-label">AI Cost Today</span>
            <span class="stat-value positive">$${stats.ai_cost}</span>
        </div>
    </div>

    <div class="footer">
        <p>Intelligence Moat • HVAC Digital Twin Demo</p>
        <button class="refresh-btn" onclick="location.reload()">🔄 Refresh Data</button>
    </div>

    <script>
        console.log('Dashboard loaded:', new Date());
        console.log('Stats:', ${JSON.stringify(stats)});
    </script>
</body>
</html>`;

return { html };
